        $q=$this->db->getQuery(true)->select('COUNT(*)')->from($this->db->quoteName('#__fdshop_orders'))->where('user_id='.(int)$userId);$this->db->setQuery($q);$total=(int)$this->db->loadResult();
        $q=$this->db->getQuery(true)->select(['o.id','o.order_number','o.created','o.modified','o.order_status','o.grand_total','o.currency','o.shipment_id','o.shipment_name','o.payment_method_name','o.withdrawal_status','o.withdrawal_declared_at','o.withdrawal_decision_text','s.status_name','sr.id AS open_shipment_request_id'])->from($this->db->quoteName('#__fdshop_orders','o'))->leftJoin($this->db->quoteName('#__fdshop_order_statuses','s').' ON s.id=o.order_status_id')->leftJoin($this->db->quoteName('#__fdshop_order_shipment_requests','sr')." ON sr.order_id=o.id AND sr.status='open'")->where('o.user_id='.(int)$userId)->order('o.created DESC');$this->db->setQuery($q,$offset,$limit);$orders=(array)$this->db->loadObjectList();
        $selected=null;$items=[];$bundles=[];
        if($orderId){$selected=$this->ownedOrder($userId,$orderId);$q=$this->db->getQuery(true)->select('*')->from($this->db->quoteName('#__fdshop_order_items'))->where('order_id='.(int)$orderId)->where('is_removed=0')->order('id');$this->db->setQuery($q);$items=(array)$this->db->loadObjectList();$q=$this->db->getQuery(true)->select('*')->from($this->db->quoteName('#__fdshop_order_bundles'))->where('order_id='.(int)$orderId)->where('is_removed=0')->order('id');$this->db->setQuery($q);$bundles=(array)$this->db->loadObjectList();if($bundles!==[]){$bundleIds=array_map(static fn($bundle)=>(int)$bundle->id,$bundles);$q=$this->db->getQuery(true)->select('*')->from($this->db->quoteName('#__fdshop_order_bundle_items'))->where('order_bundle_id IN ('.implode(',',$bundleIds).')')->where('is_removed=0')->order('order_bundle_id,id');$this->db->setQuery($q);$grouped=[];foreach((array)$this->db->loadObjectList() as $bundleItem)$grouped[(int)$bundleItem->order_bundle_id][]=$bundleItem;foreach($bundles as $bundle)$bundle->items=$grouped[(int)$bundle->id]??[];}}
        $q=$this->db->getQuery(true)->select(['id','shipment_name'])->from($this->db->quoteName('#__fdshop_shipments'))->where('published=1')->order('ordering,id');$this->db->setQuery($q);$shipments=(array)$this->db->loadObjectList();
        $q=$this->db->getQuery(true)->select('*')->from($this->db->quoteName('#__fdshop_config'))->where('id=1');$this->db->setQuery($q);$config=$this->db->loadObject();
        $q=$this->db->getQuery(true)->select(['event_type','event_title','created'])->from($this->db->quoteName('#__fdshop_user_history'))->where('user_id='.(int)$userId)->order('created DESC');$this->db->setQuery($q,0,8);$history=(array)$this->db->loadObjectList();
        $lastF3Submission=null;foreach($history as $entry)if((string)$entry->event_type==='f3_documents_submitted'){$lastF3Submission=$entry->created;break;}
        return compact('orders','total','page','limit','selected','items','bundles','shipments','config','history','lastF3Submission')+['profile'=>$this->profile($userId),'profile_config'=>$this->profileConfiguration(),'user'=>$this->user($userId),'buyer_status'=>$this->eligibility->userStatus($userId),'username_change_allowed'=>(bool)ComponentHelper::getParams('com_users')->get('change_login_name',0),'watchlist'=>$this->watchlist->forUser($userId)];
